import pytest

from pysnooper import utils


class ReprFails:
    def __repr__(self):
        raise ValueError('nope')


class WithNewlines:
    def __repr__(self):
        return 'a\r\nb'


class Custom:
    def __repr__(self):
        return 'default repr'


def test_basic_repr():
    result = utils.get_shortish_repr(42)
    assert result == '42'


def test_custom_repr_type_condition():
    result = utils.get_shortish_repr(
        Custom(), custom_repr=((Custom, lambda x: 'CUSTOM'),))
    assert result == 'CUSTOM'


def test_custom_repr_callable_condition():
    result = utils.get_shortish_repr(
        Custom(),
        custom_repr=((lambda x: isinstance(x, Custom), lambda x: 'CUSTOM2'),))
    assert result == 'CUSTOM2'


def test_custom_repr_no_match_falls_back_to_repr():
    result = utils.get_shortish_repr(
        Custom(), custom_repr=((int, lambda x: 'INT'),))
    assert result == 'default repr'


def test_repr_failure():
    result = utils.get_shortish_repr(ReprFails())
    assert result == 'REPR FAILED'


def test_newlines_removed():
    result = utils.get_shortish_repr(WithNewlines())
    assert result == 'ab'


def test_normalize():
    result = utils.get_shortish_repr(object(), normalize=True)
    assert result == '<object object>'


def test_normalize_false_keeps_address():
    result = utils.get_shortish_repr(object())
    assert ' at 0x' in result


def test_max_length_truncates():
    result = utils.get_shortish_repr('a' * 100, max_length=10)
    assert result == 'aaa...aaaa'
    assert len(result) == 10


def test_max_length_short_string_unchanged():
    result = utils.get_shortish_repr('abc', max_length=10)
    assert result == 'abc'


def test_max_length_falsy():
    result = utils.get_shortish_repr('a' * 100, max_length=None)
    assert result == 'a' * 100


def test_repr_failure_with_normalize_and_max_length():
    result = utils.get_shortish_repr(ReprFails(), max_length=8, normalize=True)
    assert result == 'RE...LED'
    assert len(result) == 8
